# t14-keep
import time
import json
from collections import OrderedDict

# 記憶體中儲存留言資料
messages = OrderedDict()
message_id_counter = 0

def handle(method, path, body):
    global message_id_counter

    if method == 'GET' and path == '/messages':
        # 取得所有留言，並依時間排序（新到舊）
        sorted_messages = sorted(messages.values(), key=lambda x: x['timestamp'], reverse=True)
        return (200, {'messages': sorted_messages, 'count': len(sorted_messages)})

    elif method == 'POST' and path == '/messages':
        # 新增一筆留言
        try:
            data = json.loads(body.decode('utf-8'))
            content = data.get('content', '').strip()
            nickname = data.get('nickname', '').strip()
            if not content:
                return (400, {'error': '留言內容不能為空'})
            if not nickname:
                return (400, {'error': '暱稱不能為空'})
            if len(content) > 200:
                return (400, {'error': '留言內容不能超過200字'})
            if len(nickname) > 20:
                return (400, {'error': '暱稱不能超過20字'})

            message_id_counter += 1
            timestamp = time.time()
            messages[message_id_counter] = {
                'id': message_id_counter,
                'content': content,
                'timestamp': timestamp,
                'likes': 0,
                'nickname': nickname
            }
            return (201, messages[message_id_counter])
        except Exception as e:
            return (400, {'error': '無效的JSON格式'})

    elif method == 'PATCH' and path.startswith('/messages/') and path.endswith('/like'):
        # 增加指定留言的點讚數
        try:
            message_id = int(path.split('/')[3])
            if message_id not in messages:
                return (404, {'error': '留言不存在'})

            messages[message_id]['likes'] += 1
            return (200, messages[message_id])
        except Exception as e:
            return (400, {'error': '無效的留言ID'})

    elif method == 'DELETE' and path.startswith('/messages/') and len(path.split('/')) == 3:
        # 刪除指定的留言
        try:
            message_id = int(path.split('/')[3])
            if message_id not in messages:
                return (404, {'error': '留言不存在'})

            del messages[message_id]
            return (200, {'message': '留言已刪除'})
        except Exception as e:
            return (400, {'error': '無效的留言ID'})

    else:
        return (404, {'error': 'API端點不存在'})

