document.addEventListener('DOMContentLoaded', () => {
    const messageForm = document.getElementById('messageForm');
    const nicknameInput = document.getElementById('nicknameInput');
    const messageInput = document.getElementById('messageInput');
    const messagesContainer = document.getElementById('messagesContainer');
    const countMessage = document.getElementById('countMessage');
    const pageTitle = document.getElementById('pageTitle');

    // 重新整理留言列表
    async function loadMessages() {
        try {
            const response = await fetch('api/messages');
            const result = await response.json();
            const messages = result.messages || result;
            const count = result.count;
            displayMessages(messages);
            displayCount(count);
            updatePageTitle(count);
        } catch (error) {
            console.error('載入留言失敗:', error);
        }
    }

    // 顯示留言列表
    function displayMessages(messages) {
        messagesContainer.innerHTML = '';
        messages.forEach(msg => {
            const messageDiv = document.createElement('div');
            messageDiv.className = 'message';
            messageDiv.innerHTML = `
                <p>${msg.content}</p>
                <div class="message-info">
                    <span>時間: ${formatTimestamp(msg.timestamp)}</span>
                    <span>暱稱: ${msg.nickname || '匿名'}</span>
                    <button class="like-btn" data-id="${msg.id}">👍 點讚 (${msg.likes})</button>
                    <button class="delete-btn" data-id="${msg.id}">🗑️ 刪除</button>
                </div>
            `;
            messagesContainer.appendChild(messageDiv);
        });

        // 綁定點讚按鈕事件
        document.querySelectorAll('.like-btn').forEach(button => {
            button.addEventListener('click', async (e) => {
                const id = e.target.dataset.id;
                try {
                    await fetch(`api/messages/${id}/like`, { method: 'PATCH' });
                    loadMessages(); // 重新載入留言
                } catch (error) {
                    console.error('點讚失敗:', error);
                }
            });
        });

        // 綁定刪除按鈕事件
        document.querySelectorAll('.delete-btn').forEach(button => {
            button.addEventListener('click', async (e) => {
                const id = e.target.dataset.id;
                try {
                    await fetch(`api/messages/${id}`, { method: 'DELETE' });
                    loadMessages(); // 重新載入留言
                } catch (error) {
                    console.error('刪除失敗:', error);
                }
            });
        });
    }

    // 顯示留言總數
    function displayCount(count) {
        countMessage.textContent = `總共有 ${count} 筆留言`;
        countMessage.style.textAlign = 'center';
        countMessage.style.marginTop = '10px';
        countMessage.style.color = '#4caf50';
    }

    // 更新頁面標題顯示留言數
    function updatePageTitle(count) {
        pageTitle.textContent = `夜間留言簿 (${count} 筆留言)`;
    }

    // 格式化時間戳為 24 小時制
    function formatTimestamp(timestamp) {
        const date = new Date(timestamp * 1000); // 轉換為毫秒
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        const hours = String(date.getHours()).padStart(2, '0');
        const minutes = String(date.getMinutes()).padStart(2, '0');
        return `${year}/${month}/${day} ${hours}:${minutes}`;
    }

    // 提交新留言
    messageForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        const nickname = nicknameInput.value.trim();
        const content = messageInput.value.trim();
        if (!content || !nickname) return;

        try {
            await fetch('api/messages', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ nickname, content })
            });
            nicknameInput.value = '';
            messageInput.value = '';
            loadMessages(); // 重新載入留言
        } catch (error) {
            console.error('送出留言失敗:', error);
        }
    });

    // 初始載入留言
    loadMessages();
});

